export function requireBodyFixedSunDirection(bodyId) {
  const direction = BODY_FIXED_SUN_DIRECTIONS[bodyId];
  if (direction === undefined) {
    throw new TypeError(`No prepared solar geometry for body: ${bodyId}.`);
  }
  return direction;
}

